      "suite-guided-prediction": "dự đoán theo hướng dẫn",
      "suite-guided-prediction-label": "nhãn dự đoán có hướng dẫn",
      "suite-guided-prompt": "bộ hướng dẫn-nhắc",
      "suite-guided-reset": "thiết lập lại theo hướng dẫn",
